// Extract event data and tenant configuration
const body = $input.first().json.body || $input.first().json;

const eventType = body.eventType || 'UNKNOWN';
const tenantId = body.tenantId || 'tenant-demo-01';
const payload = body.data || {};

// Format recipient phone number to E.164 (remove spaces, dashes)
let cleanPhone = (payload.phone || payload.whatsappPhone || payload.patientPhone || '').replace(/[^0-9+]/g, '');
if (cleanPhone.startsWith('00')) {
  cleanPhone = '+' + cleanPhone.substring(2);
} else if (!cleanPhone.startsWith('+') && cleanPhone.length >= 10) {
  cleanPhone = '+' + cleanPhone;
}

return [{
  json: {
    eventId: body.eventId || `evt_${Date.now()}`,
    eventType,
    tenantId,
    recipientPhone: cleanPhone,
    patientName: payload.fullNameAr || payload.patientName || payload.fullName || 'المريض الكريم',
    payload,
    timestamp: new Date().toISOString()
  }
}];

// Prepare Patient Onboarding WhatsApp Message with Emojis & Credentials
const data = $input.first().json;
const p = data.payload;

const messageAr = `مرحباً بك يا ${data.patientName} في ${p.clinicName || 'مجمعنا الطبي'} 🏥✨

تم فتح ملفك الطبي ورقم سجلك هو: *${p.medicalRecordNumber || 'MRN-PENDING'}*

🔐 *بيانات الدخول لبوابتك الصحية:*
👤 اسم المستخدم / الهاتف: ${data.recipientPhone}
🔑 كلمة المرور المؤقتة: *${p.temporaryPassword || 'Aegis@2026!'}*

📲 رابط البوابة وتطبيق المريض:
https://aegishealth.med/patient/dashboard

🎧 للإرشادات الصوتية خطوة بخطوة، اضغط هنا:
https://aegishealth.med/voice-guide/${p.patientId || 'demo'}

نتمنى لك دوام الصحة والعافية! 💚`;

return [{
  json: {
    ...data,
    whatsappMessage: messageAr,
    messageType: 'onboarding'
  }
}];

// Prepare Appointment Confirmation WhatsApp Message
const data = $input.first().json;
const p = data.payload;

const messageAr = `تأكيد حجز الموعد الطبي 📅🩺

عزيزنا المريض: *${data.patientName}*
تم تأكيد موعدك مع: *${p.clinicianName || 'الطبيب الاستشاري'}*

🗓️ الموعد: *${p.dateFormatted || p.scheduledAt || 'اليوم'}*
⏰ الوقت: *${p.timeSlot || '04:30 PM'}*
📍 العيادة: *${p.clinicName || 'العيادات التخصصية'}* — غرفة: *${p.room || '102'}*

⚠️ *إرشادات قبل الحضور:*
${(p.preparationChecklist || ['يرجى الحضور قبل الموعد بـ 15 دقيقة', 'إحضار الهوية الوطنية']).map(c => '• ' + c).join('\n')}

لإلغاء أو تعديل الموعد يرجى الرد على هذه الرسالة. 🌿`;

return [{
  json: {
    ...data,
    whatsappMessage: messageAr,
    messageType: 'appointment_confirmation'
  }
}];

// Prepare Prescription with Emoji Badges & Voice Guidance
const data = $input.first().json;
const p = data.payload;

const meds = p.medications || [];
const medListText = meds.map((m, i) => {
  return `${i + 1}. *${m.nameAr || m.nameEn}* ${m.formEmoji || '💊'}
   الجرعة: ${m.dosage}
   التوقيت: ${m.timingEmoji || '☀️🌙'} (${m.frequencyAr || m.frequencyEn})
   إرشادات الطعام: ${m.foodInstructionAr || 'مع أو بعد الأكل'} 🍽️`;
}).join('\n\n');

const messageAr = `روشتتك الطبية الإلكترونية 📋💊

عزيزنا: *${data.patientName}*
أصدر لك *${p.doctorName || 'الطبيب المعالج'}* خطة العلاج التالية:

${medListText || '1. أدوية خافضة للضغط ومكملات غذائية 💊'}

🔊 *للاستماع إلى الإرشادات الصوتية لجرعاتك:*
https://aegishealth.med/rx/voice/${p.prescriptionId || 'demo'}

مع تمنياتنا لك بالشفاء العاجل! 💚`;

return [{
  json: {
    ...data,
    whatsappMessage: messageAr,
    messageType: 'prescription_guidance'
  }
}];

// Clinical AI Triage Chatbot Logic
const data = $input.first().json;
const p = data.payload;
const query = p.incomingMessage || p.query || '';

let aiReply = '';
if (query.includes('صداع') || query.includes('ضغط') || query.includes('ألم')) {
  aiReply = `أهلاً بك يا ${data.patientName}، أنا المساعد الطبي الذكي لمجمع عافية 🩺.\n\nبناءً على الأعراض المذكورة، يرجى قياس ضغط الدم والراحة في مكان هادئ. إذا استمر العارض، نوصي بحجز استشارة فورية مع طبيب الباطنة أو القلب.\n\nهل ترغب في حجز موعد الآن؟`;
} else if (query.includes('موعد') || query.includes('حجز')) {
  aiReply = `أهلاً بك! يمكنك استعراض المواعيد المتاحة لأطبائنا وحجز موعدك فوراً عبر هذا الرابط:\nhttps://aegishealth.med/find-doctor\n\nأو أخبرني بالتخصص المطلوب لأساعدك.`;
} else {
  aiReply = `أهلاً بك في خدمة الرعاية الصحية الذكية 🏥.\nرسالتك مسجلة وسيتم توجيهها للفريق الطبي المختص. في حالات الطوارئ يرجى التوجه فوراً لأقرب قسم طوارئ.`;
}

return [{
  json: {
    ...data,
    whatsappMessage: aiReply,
    messageType: 'ai_triage'
  }
}];
